// Generates public/firebase-messaging-sw.js at build/dev time from the
// VITE_FIREBASE_* env vars, so the Firebase web config lives in ONE place
// (the env) instead of being hardcoded in a committed service-worker file.
//
// The service worker can't read import.meta.env (static files in public/ are
// not processed by Vite), and it must have the config available for BACKGROUND
// messages (page closed), so injecting at build is the clean option. The
// generated file is gitignored.
//
// Firebase config values (apiKey, projectId, messagingSenderId, appId) are
// client-safe by Firebase's design — they ship in the JS bundle regardless —
// so writing them into the SW is not a secret leak.
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { loadEnv } from 'vite';

// Keep this in sync with the `firebase` package major in package.json. The SW
// loads the compat build from the CDN (importScripts can't bundle the modular
// SDK); the app side uses the bundled modular SDK — same Firebase project.
const FIREBASE_SDK_VERSION = '11.10.0';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, '..');
const outFile = path.join(root, 'public', 'firebase-messaging-sw.js');

const mode = process.env.NODE_ENV || 'production';
const env = loadEnv(mode, root, 'VITE_');

const config = {
  apiKey: env.VITE_FIREBASE_API_KEY || '',
  projectId: env.VITE_FIREBASE_PROJECT_ID || '',
  messagingSenderId: env.VITE_FIREBASE_MESSAGING_SENDER_ID || '',
  appId: env.VITE_FIREBASE_APP_ID || '',
};

const configured = config.apiKey && config.projectId && config.messagingSenderId && config.appId;

const header = '// AUTO-GENERATED by scripts/generate-firebase-sw.mjs — do not edit; do not commit.\n';

const sw = configured
  ? `${header}importScripts('https://www.gstatic.com/firebasejs/${FIREBASE_SDK_VERSION}/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/${FIREBASE_SDK_VERSION}/firebase-messaging-compat.js');

firebase.initializeApp(${JSON.stringify(config)});
const messaging = firebase.messaging();

messaging.onBackgroundMessage((payload) => {
  const notification = payload.notification || {};
  const data = payload.data || {};
  self.registration.showNotification(notification.title || 'Byblos', {
    body: notification.body || '',
    icon: '/android-chrome-192x192.png',
    badge: '/android-chrome-192x192.png',
    data,
  });
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const target = event.notification.data && (event.notification.data.path || event.notification.data.url);
  const url = (typeof target === 'string' && target.startsWith('/')) ? target : '/';
  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      for (const client of clientList) {
        if ('focus' in client) {
          if ('navigate' in client) { client.navigate(url); }
          return client.focus();
        }
      }
      return self.clients.openWindow(url);
    })
  );
});
`
  : `${header}// VITE_FIREBASE_* env vars are not set, so Firebase messaging is not initialized.
// This empty worker still registers so the app satisfies Chrome's PWA install
// criteria; web push is simply inactive until the config is provided.
self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', (event) => event.waitUntil(self.clients.claim()));
`;

writeFileSync(outFile, sw, 'utf8');
console.log(`[generate-firebase-sw] wrote ${path.relative(root, outFile)} (firebase ${configured ? 'configured' : 'NOT configured — inactive worker'})`);
